def transform(grid):
    """Mark with 2 the background gaps between colored cells on each row/column."""
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v != bg]
        if len(cols) >= 2:
            for c in range(cols[0] + 1, cols[-1]):
                if out[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if len(rows) >= 2:
            for r in range(rows[0] + 1, rows[-1]):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out

